import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const g=JSON.parse('{"title":"SettingsPage","description":"","frontmatter":{},"headers":[],"relativePath":"components/settings-page.md","filePath":"components/settings-page.md"}'),r={name:"components/settings-page.md"};function s(i,t,n,h,c,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="settingspage" tabindex="-1">SettingsPage <a class="header-anchor" href="#settingspage" aria-label="Permalink to &quot;SettingsPage&quot;">​</a></h1><p>SettingsPage is the frame of a settings page: the trail, the title, the tabs and the sections.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for pages where people read and change settings. Pass the trail to the page in <code>crumbs</code>, and the pages of the settings in <code>tabs</code> with the <code>current</code> one; put <a href="./section">Section</a>s in the children. Any other page is a <a href="./page">Page</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The title of the page</td></tr><tr><td><code>crumbs</code></td><td><code>[]</code></td><td>The trail to the page, <code>{ label, href?, onclick? }[]</code></td></tr><tr><td><code>crumbsLabel</code></td><td></td><td>The name of the trail</td></tr><tr><td><code>tabs</code></td><td></td><td>The tabs, <code>{ id, label, href? }[]</code></td></tr><tr><td><code>current</code></td><td></td><td>The id of the current tab</td></tr><tr><td><code>tabsLabel</code></td><td></td><td>The name of the tabs</td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the tab that is opened</td></tr><tr><td><code>titleEnd</code></td><td></td><td>A borderless icon button beside the title (a snippet)</td></tr><tr><td><code>children</code></td><td>required</td><td>The sections</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./page">Page</a> of the settings width, with a <a href="./page-header">PageHeader</a> as its head: the <a href="./crumbs">Crumbs</a>, then the title. With tabs, the page is <code>flush</code> and the text of the tabs is pad-lg below the title; the first section is gap-lg below the tabs&#39; line. Without tabs, the first section is pad-lg below the title. The sections are stacked with gap 0; each brings its own distance and line. Below 48rem the margin at the sides is gap-md.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/settings-page/" title="SettingsPage" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/settings-page/" target="_blank" rel="noopener">SettingsPage</a></figcaption></figure>',10)])])}const b=e(r,[["render",s]]);export{g as __pageData,b as default};
